args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel (MAX(?death) AS ?maxDeathDate) WHERE {
  VALUES ?film { dbr:Too_Tough_to_Kill dbr:Jhoothi }
  OPTIONAL {
    { ?film dbo:director ?dir } UNION { ?film dbp:director ?dir }
    OPTIONAL { ?dir dbo:deathDate ?d1 }
    OPTIONAL { ?dir dbp:death_date ?d2 }
    BIND(COALESCE(?d1, ?d2) AS ?death)
  }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = "en") }
}
GROUP BY ?film ?filmLabel
ORDER BY DESC(?maxDeathDate)

